import { API_BASE_URL } from '../config/api';

export type ColumnId = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  column: ColumnId;
}

export const COLUMN_ORDER: ColumnId[] = ['todo', 'in-progress', 'done'];

export async function fetchTasks(): Promise<Task[]> {
  const response = await fetch(`${API_BASE_URL}/tasks`);
  if (!response.ok) throw new Error(`Tasks failed with status ${response.status}`);
  return (await response.json()) as Task[];
}

export async function moveTask(id: string, column: ColumnId): Promise<Task> {
  const response = await fetch(`${API_BASE_URL}/tasks/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ column }),
  });
  if (!response.ok) throw new Error(`Move failed with status ${response.status}`);
  return (await response.json()) as Task;
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchTasks, moveTask, COLUMN_ORDER, type ColumnId, type Task } from '../services/tasks';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  danger: '#ff6b5e',
  muted: '#8a8f8a',
  bgAlt: '#171b17',
  textMuted: '#a8ada6',
  surface: '#1a1f1a',
  text: '#f5f5f0',
  borderAlt: '#2a2f2a',
}

const COLUMN_LABEL: Record<ColumnId, string> = { todo: 'To do', 'in-progress': 'In progress', done: 'Done' };

export function TaskBoardScreen(): JSX.Element {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

    const load = useCallback(async () => {

    try {
      const data = await fetchTasks();
      setTasks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load tasks.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const byColumn = useMemo(() => {
    const out: Record<ColumnId, Task[]> = { todo: [], 'in-progress': [], done: [] };
    for (const task of tasks) out[task.column].push(task);
    return out;
  }, [tasks]);

  const advance = useCallback(async (task: Task) => {
    const index = COLUMN_ORDER.indexOf(task.column);
    if (index >= COLUMN_ORDER.length - 1) return;
    const next: ColumnId = COLUMN_ORDER[index + 1];
    setTasks(prev => prev.map(t => (t.id === task.id ? { ...t, column: next } : t)));
    try {
      const confirmed = await moveTask(task.id, next);
      setTasks(prev => prev.map(t => (t.id === task.id ? confirmed : t)));
    } catch {
      setTasks(prev => prev.map(t => (t.id === task.id ? { ...t, column: task.column } : t)));
    }
  }, []);

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && tasks.length === 0 && <Text style={styles.empty}>No tasks yet.</Text>}
      {!loading && !error && tasks.length > 0 && (
        <ScrollView horizontal contentContainerStyle={styles.board}>
          {COLUMN_ORDER.map(column => (
            <View key={column} style={styles.column}>
              <Text style={styles.columnHeader}>
                {COLUMN_LABEL[column]} · {byColumn[column].length}
              </Text>
              {byColumn[column].map(task => (
                <View key={task.id} style={styles.card}>
                  <Text style={styles.cardTitle}>{task.title}</Text>
                  {column !== 'done' && (
                    <TouchableOpacity style={styles.move} onPress={() => void advance(task)} accessibilityRole="button" accessibilityLabel={`Move ${task.title} forward`}>
                      <Text style={styles.moveText}>→</Text>
                    </TouchableOpacity>
                  )}
                </View>
              ))}
            </View>
          ))}
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
  board: { padding: 16, gap: 16 },
  column: { width: 260, backgroundColor: colors.bgAlt, borderRadius: 10, padding: 12 },
  columnHeader: { color: colors.textMuted, fontWeight: '700', marginBottom: 10 },
  card: { backgroundColor: colors.surface, borderRadius: 8, padding: 12, marginBottom: 10 },
  cardTitle: { color: colors.text },
  move: { alignSelf: 'flex-end', marginTop: 8, backgroundColor: colors.borderAlt, borderRadius: 6, paddingHorizontal: 12, paddingVertical: 6 },
  moveText: { color: colors.accent, fontWeight: '700' },
});
